const STATEN: Record<VliegerStaat, { El: () => ReactElement; w: number; h: number }> = {
  // figma: State=Wolken
  "wolken": { El: Staat0, w: 129, h: 99 },
  // figma: State=Wind
  "wind": { El: Staat1, w: 129, h: 99 },
  // figma: State=Mist
  "mist": { El: Staat2, w: 129, h: 101 },
  // figma: State=Regen
  "regen": { El: Staat3, w: 149, h: 101 },
  // figma: State=Default
  "default": { El: Staat4, w: 563, h: 89 },
  // figma: State=Zonnig
  "zonnig": { El: Staat5, w: 129, h: 100 },
  // figma: State=Intake
  "intake": { El: Staat6, w: 80, h: 152.258 },
};

export type MascotteVliegerProps = {
  state?: VliegerStaat;
  /** Gewenste hoogte in punten; de tekening schaalt als geheel mee. */
  hoogte?: number;
  style?: StyleProp<ViewStyle>;
};

export function MascotteVlieger({ state = "wolken", hoogte, style }: MascotteVliegerProps) {
  const { El, w, h } = STATEN[state] ?? STATEN.wolken;
  const schaal = hoogte ? hoogte / h : 1;
  return (
    <View style={[{ width: w * schaal, height: h * schaal, overflow: "visible" }, style]}>
      <View style={{ width: w, height: h, transform: [{ scale: schaal }], transformOrigin: "top left" }}>
        <El />
      </View>
    </View>
  );
}
